// 共享游戏规则工具：声望读取 / 加成文案 / 攻击模块属性阈值文案
// 供 StoreUI / PlayerPanel / VenuePanel 共用，避免三处重复实现导致逻辑漂移。

export function rep_of(势力: Record<string, number> | undefined, faction: string): number {
  return Math.max(0, Number(势力?.[faction]) || 0);
}

export function bonus_text(bonus?: Record<string, number>): string {
  const list: string[] = [];
  for (const [k, v] of Object.entries(bonus ?? {})) {
    if (Number(v) > 0) list.push(`${k}+${v}`);
  }
  return list.join(' ');
}

export function attr_req_text(req?: { 智力?: number; 灵能?: number }): string {
  const int = Number(req?.智力 || 0);
  const psi = Number(req?.灵能 || 0);
  const parts: string[] = [];
  if (int > 0) parts.push(`智力≥${int}`);
  if (psi > 0) parts.push(`灵能≥${psi}`);
  return parts.join(' 且 ');
}