// MVU 变量结构 —— 《合成兽人会不会梦到电子学长》
// 运行时已注入全局 z（Zod v4）与 _（lodash），本文件不写任何引入语句
// —— 数值容错解析 ——
// 正文 AI 常把数值写成「48+350=398」「1900 信用点」「1,200」「约 50」等不够规范的形式。
// z.coerce 用 Number() 会把含文字/算式的字符串解析成 NaN 后把字段清零，故这里主动清洗：
// 去掉单位/修饰词与千分位分隔，然后取**最后一个独立数字**——这恰好能对上 AI 常见的
// 「前值 + 报酬 = 最终值」这类计算式的右侧结果（48+350=398 → 398），比取第一个数字更稳。
// 注意：这仍是兜底；世界书规范要求 AI 直接写「结算后绝对总额」，禁止写算式。
function coerceNumber(v) {
    if (typeof v === 'number')
        return Number.isFinite(v) ? v : NaN;
    if (typeof v === 'string' && v.trim() !== '') {
        const cleaned = v
            .replace(/[，,、._·\s]/g, '') // 去中文/英文分隔符与空白
            .replace(/(信用点|点|金币|％|%|约|左右|元|前面|之前|元)/g, ''); // 去常见单位/修饰词
        const all = cleaned.match(/-?\d+(?:\.\d+)?/g);
        const last = all && all.length ? all[all.length - 1] : null;
        if (last) {
            const n = Number(last);
            if (Number.isFinite(n))
                return n;
        }
    }
    return NaN;
}
// 构造一个「剥离文本后 clamp 到 [min,max]」的数字 schema。
// 清洗取数失败（如纯文本、无数字）时回退为 min，保证字段类型恒为 number、不把 AI 的字符串
// 塞进数字型跑挂；规避 z.coerce 把坏字符串转 NaN 后写 0 的问题。
function numberField(min, max) {
    return z.number().or(z.string()).prefault(0).transform((v) => {
        const n = coerceNumber(v);
        if (!Number.isFinite(n)) {
            const cur = typeof v === 'number' ? v : Number(v);
            return Number.isFinite(cur) ? _.clamp(cur, min, max) : min;
        }
        return _.clamp(n, min, max);
    });
}
// 通用非负金额（下限 0，上限不设）：用于 资产.金钱 / 报酬.货币 等可累加的资金
const moneyField = numberField(0, Number.MAX_SAFE_INTEGER);
// 供「需动态增键的记录值」使用的数字：不做 .transform（transform 会让 tavern-helper 把
// 记录节点编译成不可扩展的封闭对象，导致 add 新键被拒如 关系.好感度.新NPC 报 SCHEMA 违规）。
// 改用 z.coerce.number 直接取值并按 [min,max] clamp，值恒为 number、节点保持可扩展。
// 注意：值类型（z.record 的第 2 个参数）也严禁加 .describe()——describe 会让编译器把值
// 提升成 $defs 里的 $ref，运行时该记录同样被当成「不可扩展」，add 新键报 SCHEMA 违规。
function mapNumber(min, max) {
    return z.coerce.number().min(min).max(max).catch(min);
}
