// 场所·货品单一数据源
// 所有消费场所及其可购货品在此集中定义，StoreUI（商店交易）与 VenuePanel（场所目录）共用，
// 保证名称、地段、声望门禁在整条产线中始终一致。
//
// 货品生成模板说明：
// - 每个「场所」只需提供 compact 的 goods 描述（名称/价格/描述/效果），
//   运行时 StoreUI 依据 kind_type 自动完成：门禁继承、已持有判定、义体到店安装、结算入账。
// - 不同场所的货品名称与功能刻意区分：命名参考世界书《义体外观与工艺标准》的厂商命名规范。

export type Gate = { faction: string; threshold: number };

export type ImplantSlot =
  | '脑机接口'
  | '眼部'
  | '听觉声带'
  | '脊柱'
  | '心脏'
  | '皮肤'
  | '脏器'
  | '左臂'
  | '右臂'
  | '左腿'
  | '右腿';

export type GoodKindType = 'money' | '房产' | '载具' | '红区' | '义体' | '武器' | '委托';

export type WeaponFamily = '科技' | '魔能' | '黑客攻击模块';

// 委托难度：与 schema「任务.当前委托.难度」对齐
export type QuestDifficulty = '简单' | '普通' | '困难' | '极难';

// 委托进度点总量：与 世界书/委托系统 对齐
export const QUEST_PROGRESS_TOTAL: Record<QuestDifficulty, number> = {
  简单: 2,
  普通: 3,
  困难: 4,
  极难: 5,
};

// 九界居住层级建造顺序（灵网层为数字层面、单独推进，不入此列）
