// —— 义体/武器类店铺按时段轮换货架 ——
// 时段映射：清晨/上午→早市，下午→午市，傍晚/深夜→夜市；无 goods_sets 的店恒用 goods
export const SESSION_LABELS = ['早市', '午市', '夜市'];

export function session_idx(session: string): number {
  const i = SESSIONS.indexOf(session as Session);
  return i <= 1 ? 0 : i === 2 ? 1 : 2;
}

export function goods_of(venue: Venue, session: string, shelf_override = -1): Good[] {
  const sets = venue.goods_sets;
  if (!sets || sets.length === 0) return venue.goods;
  const idx = shelf_override >= 0 ? shelf_override % sets.length : session_idx(session);
  const shelf = sets[Math.min(idx, sets.length - 1)] ?? venue.goods;
  // 情报类店同时展示固定情报（goods）与当前轮换货架（sets）；义体/武器/攻击模块店仅展示当前货架
  if (venue.genre === '情报' && venue.goods && venue.goods.length) return [...venue.goods, ...shelf];
  return shelf;
}

export function session_label(session: string): string {
  return SESSION_LABELS[session_idx(session)] ?? '早市';
}